const providers={telegram:'https://api.telegram.org',bale:'https://tapi.bale.ai'};
const json=(value,status=200)=>new Response(JSON.stringify(value),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store'}});
const validProvider=p=>Object.hasOwn(providers,p);
export async function api(provider,token,method,body){
 try{const response=await fetch(`${providers[provider]}/bot${token}/${method}`,{method:'POST',body:body instanceof FormData?body:JSON.stringify(body),headers:body instanceof FormData?undefined:{'Content-Type':'application/json'},signal:AbortSignal.timeout(25000)});const result=await response.json();if(!response.ok||!result.ok)throw new Error('api');return result.result;}catch{throw new Error('ارتباط با '+(provider==='telegram'?'تلگرام':'بله')+' انجام نشد. توکن و اتصال را بررسی کنید.');}
}
const normalizePassword=value=>String(value||'').replace(/[۰-۹]/g,d=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d))).replace(/[٠-٩]/g,d=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)));
async function passwordHash(password,salt){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(normalizePassword(password)),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:100000,hash:'SHA-256'},key,256);return [...new Uint8Array(bits)].map(x=>x.toString(16).padStart(2,'0')).join('');}
export class BotHub {
 constructor(state,env){this.state=state;this.env=env;this.locks=new Map();}
 async verifyManagement(password){
  if(typeof password!=='string'||password.length<4||password.length>128)return false;
  let record=await this.state.storage.get('auth:password');
  if(!record){if(normalizePassword(password)!=='8145')return false;const salt=crypto.randomUUID().replaceAll('-','');record={salt,hash:await passwordHash(password,salt)};await this.state.storage.put('auth:password',record);return true;}
  return (await passwordHash(password,record.salt))===record.hash;
 }
 async alarm(){try{for(const p of Object.keys(providers))await this.sync(p);}finally{await this.state.storage.setAlarm(Date.now()+60000);}}
 async sync(provider){
  const c=await this.state.storage.get('config:'+provider);if(!c?.polling)return;
  const updates=await api(provider,c.token,'getUpdates',{offset:c.offset||0,limit:100,timeout:0});
  for(const u of updates){const m=u.message;const command=String(m?.text||'').trim().split(/\s/)[0].split('@')[0];if(m?.chat?.type==='private'&&Number.isSafeInteger(m.chat.id)){const key='sub:'+provider+':'+m.chat.id;if(command==='/start')await this.state.storage.put(key,{chat:String(m.chat.id),username:String(m.from?.username||m.chat.username||'').toLowerCase()});if(command==='/stop')await this.state.storage.delete(key);}c.offset=Math.max(c.offset||0,u.update_id+1);}
  if(updates.length)await this.state.storage.put('config:'+provider,c);
 }
 async fetch(request){
  const url=new URL(request.url);const path=url.pathname;
  try{
   if(path.startsWith('/api/hook/')){
    if(request.method!=='POST')return json({},405);const [, , ,provider,secret]=path.split('/');if(!validProvider(provider))return json({},404);
    const config=await this.state.storage.get('config:'+provider);if(!config||secret!==config.secret)return json({},403);
    const update=await request.json();const m=update.message;const command=String(m?.text||'').trim().split(/\s/)[0].split('@')[0];
    if(m?.chat?.type==='private'&&Number.isSafeInteger(m.chat.id)){
     const key='sub:'+provider+':'+m.chat.id;
     if(command==='/start')await this.state.storage.put(key,{chat:String(m.chat.id),username:String(m.from?.username||m.chat.username||'').toLowerCase()});
     if(command==='/stop')await this.state.storage.delete(key);
    }
    return json({ok:true});
   }
   let managementPassword=request.headers.get('X-Management-Password');try{managementPassword=managementPassword===null?null:decodeURIComponent(managementPassword);}catch{return json({error:'رمز درست نیست.'},403);}
   if(['/api/config','/api/whitelist','/api/password','/api/recipients'].includes(path)&&!(await this.verifyManagement(managementPassword)))return json({error:'رمز درست نیست.'},403);
   // Private migration backup: keep prior /start registrations when moving accounts.
   // Bot tokens never enter this export. Restore verifies each chat with the provider.
   if(path==='/api/recipients'&&request.method==='GET'){const result={};for(const p of Object.keys(providers))result[p]=[...(await this.state.storage.list({prefix:'sub:'+p+':'})).values()];return json(result);}
   if(path==='/api/recipients'&&request.method==='POST'){
    const {provider,entries}=await request.json();if(!validProvider(provider)||!Array.isArray(entries)||entries.length>200||entries.some(x=>!x||!/^\d{1,16}$/.test(x.chat)||typeof x.username!=='string'||!/^\w{0,64}$/.test(x.username)))return json({error:'فهرست بازیابی معتبر نیست.'},400);
    const config=await this.state.storage.get('config:'+provider);if(!config)return json({error:'ابتدا توکن این ربات را ثبت کنید.'},400);let restored=0,failed=0;
    for(const entry of entries){try{const chat=await api(provider,config.token,'getChat',{chat_id:entry.chat});if(chat.type!=='private'||String(chat.id)!==entry.chat)throw Error('chat');await this.state.storage.put('sub:'+provider+':'+entry.chat,{chat:entry.chat,username:String(chat.username||entry.username).toLowerCase()});restored++;}catch{failed++;}}
    return json({restored,failed});
   }
   if(path==='/api/password'&&request.method==='POST'){const {next,repeated}=await request.json();if(typeof next!=='string'||next.length<4||next.length>128||normalizePassword(next)!==normalizePassword(repeated))return json({error:'رمز جدید و تکرار آن درست نیست.'},400);const salt=crypto.randomUUID().replaceAll('-','');await this.state.storage.put('auth:password',{salt,hash:await passwordHash(next,salt)});return json({ok:true});}
   if(path==='/api/whitelist'&&request.method==='POST'){
    const {provider,entries}=await request.json();if(!validProvider(provider)||!Array.isArray(entries)||entries.length>200||entries.some(x=>typeof x!=='string'||!/^@?[A-Za-z0-9_]{1,64}$/.test(x)))return json({error:'فهرست باید شناسهٔ عددی یا نام کاربری باشد؛ حداکثر ۲۰۰ مورد.'},400);
    await this.state.storage.put('allow:'+provider,{enabled:entries.length>0,entries:[...new Set(entries.map(x=>x.replace(/^@/,'').toLowerCase()))]});return json({ok:true});
   }
   if(path==='/api/sync'){for(const p of Object.keys(providers))await this.sync(p);return json({ok:true});}
   if(path==='/api/status'){for(const p of Object.keys(providers))await this.sync(p);
    const status={};for(const p of Object.keys(providers)){const c=await this.state.storage.get('config:'+p);const subs=await this.state.storage.list({prefix:'sub:'+p+':'});const allow=await this.state.storage.get('allow:'+p)||{enabled:false,entries:[]};status[p]={configured:!!c,username:c?.username||'',recipients:subs.size,whitelist:allow};}return json(status);
   }
   if(path==='/api/config'&&request.method==='POST'){
    const {provider,token}=await request.json();if(!validProvider(provider)||typeof token!=='string'||!/^\d+:[A-Za-z0-9_-]{20,120}$/.test(token))return json({error:'توکن یا پیام‌رسان درست نیست.'},400);
    const me=await api(provider,token,'getMe',{});let pending=[];const hook=await api(provider,token,'getWebhookInfo',{});if(!hook.url)pending=await api(provider,token,'getUpdates',{timeout:0,limit:100});const old=await this.state.storage.get('config:'+provider);const secret=crypto.randomUUID().replaceAll('-','');
    const config={token,secret,username:me.username||'',botId:me.id,polling:provider==='telegram',offset:old?.botId===me.id?old.offset||0:0};await this.state.storage.put('config:'+provider,config);
    try{if(config.polling)await api(provider,token,'deleteWebhook',{drop_pending_updates:false});else await api(provider,token,'setWebhook',{url:url.origin+'/api/hook/'+provider+'/'+secret,allowed_updates:['message']});}catch(e){if(old)await this.state.storage.put('config:'+provider,old);else await this.state.storage.delete('config:'+provider);throw e;}
    if(old&&old.botId!==me.id){const subs=await this.state.storage.list({prefix:'sub:'+provider+':'});for(const key of subs.keys())await this.state.storage.delete(key);}
    for(const update of pending){const m=update.message;const command=String(m?.text||'').trim().split(/\s/)[0].split('@')[0];if(m?.chat?.type==='private'&&Number.isSafeInteger(m.chat.id)){const key='sub:'+provider+':'+m.chat.id;if(command==='/start')await this.state.storage.put(key,{chat:String(m.chat.id),username:String(m.from?.username||m.chat.username||'').toLowerCase()});if(command==='/stop')await this.state.storage.delete(key);}}
    await this.sync(provider);await this.state.storage.setAlarm(Date.now()+60000);return json({ok:true,username:me.username||''});
   }
   if(path==='/api/send'&&request.method==='POST'){
    if(Number(request.headers.get('Content-Length')||0)>20*1024*1024)return json({error:'فایل برای ارسال بیش از حد بزرگ است.'},413);
    const form=await request.formData();const file=form.get('file'),provider=form.get('provider'),id=form.get('id');
    const captionInput=form.get('caption');if(captionInput!==null&&(typeof captionInput!=='string'||captionInput.length>1024))return json({error:'کپشن حداکثر ۱۰۲۴ نویسه است.'},400);const caption=typeof captionInput==='string'&&captionInput.trim()?captionInput:'خروجی سند کاره چاهی';
    if(!validProvider(provider)||!(file instanceof File)||file.size>18*1024*1024||typeof id!=='string'||!/^[a-zA-Z0-9-]{1,80}$/.test(id))return json({error:'فایل یا درخواست معتبر نیست.'},400);
    const head=new Uint8Array(await file.slice(0,5).arrayBuffer());if(new TextDecoder().decode(head)!=='%PDF-')return json({error:'فقط PDF قابل ارسال است.'},400);
    await this.sync(provider);const config=await this.state.storage.get('config:'+provider);if(!config)return json({error:'ابتدا توکن این ربات را ثبت کنید.'},400);
    const currentAllow=await this.state.storage.get('allow:'+provider);
    if(currentAllow?.enabled&&currentAllow.entries.some(x=>!/^\d+$/.test(x))){const subs=await this.state.storage.list({prefix:'sub:'+provider+':'});for(const [key,sub]of subs){if(sub.username)continue;try{const chat=await api(provider,config.token,'getChat',{chat_id:sub.chat});sub.username=String(chat.username||'').toLowerCase();await this.state.storage.put(key,sub);}catch{}}}
    const jobKey='job:'+provider+':'+id;const previous=this.locks.get(jobKey)||Promise.resolve();let release;const gate=new Promise(resolve=>{release=resolve;});const queued=previous.then(()=>gate);this.locks.set(jobKey,queued);await previous;try{let job=await this.state.storage.get(jobKey);
    if(!job){const subs=await this.state.storage.list({prefix:'sub:'+provider+':'});const allow=await this.state.storage.get('allow:'+provider);job={chats:[...subs.values()].filter(x=>!allow?.enabled||!allow.entries.length||allow.entries.includes(x.chat)||allow.entries.includes(x.username)).map(x=>x.chat),done:{},created:Date.now()};await this.state.storage.put(jobKey,job);}
    // Only successful recipients are marked. An explicit retry skips those who
    // already received this export; failures stay retryable.
    const allow=await this.state.storage.get('allow:'+provider);{const subs=await this.state.storage.list({prefix:'sub:'+provider+':'});job.chats=job.chats.filter(chat=>{const sub=subs.get('sub:'+provider+':'+chat);return sub&&(!allow?.enabled||!allow.entries.length||allow.entries.includes(chat)||allow.entries.includes(sub.username));});}
    let sent=0,failed=0;const pending=job.chats.filter(chat=>!job.done[chat]);
    for(const chat of pending.slice(0,10)){
     const body=new FormData();body.set('chat_id',chat);body.set('document',file,file.name);body.set('caption',caption);
     try{await api(provider,config.token,'sendDocument',body);job.done[chat]=true;sent++;await this.state.storage.put(jobKey,job);}catch{failed++;}
    }
    const remaining=job.chats.filter(chat=>!job.done[chat]).length;
    const jobs=await this.state.storage.list({prefix:'job:'});for(const [key,value]of jobs)if(value.created<Date.now()-86400000)await this.state.storage.delete(key);
    return json({sent,failed,remaining,total:job.chats.length});}finally{release();if(this.locks.get(jobKey)===queued)this.locks.delete(jobKey);}
   }
   return json({error:'مسیر پیدا نشد.'},404);
  }catch(e){return json({error:e instanceof Error&&/[\u0600-\u06ff]/.test(e.message)?e.message:'درخواست انجام نشد؛ دوباره تلاش کنید.'},502);}
 }
}
export default {async fetch(request,env){
 const u=new URL(request.url);if(!u.pathname.startsWith('/api/'))return serveSite(request);
 const origin=request.headers.get('Origin');const allowed=(env.ALLOWED_ORIGINS||'').split(',').filter(Boolean);if(origin&&origin!==u.origin&&!allowed.includes(origin))return json({error:'این سایت اجازهٔ اتصال ندارد.'},403);
 const cors=origin?{'Access-Control-Allow-Origin':origin,'Access-Control-Allow-Headers':'Content-Type,X-Management-Password','Access-Control-Allow-Methods':'GET,POST,OPTIONS','Vary':'Origin'}:{};
 if(request.method==='OPTIONS')return new Response(null,{headers:cors});
 const hub=env.BOT_HUB.get(env.BOT_HUB.idFromName('main'));const res=await hub.fetch(request);const headers=new Headers(res.headers);for(const [k,v]of Object.entries(cors))headers.set(k,v);return new Response(res.body,{status:res.status,headers});
}};

const SITE_ASSETS={"/index.html":{"type":"text/html","data":""},"/logo-source.jpg":{"type":"image/jpeg","data":""},"/logo.svg":{"type":"image/svg+xml","data":""},"/manifest.webmanifest":{"type":"application/manifest+json","data":""},"/precache.json":{"type":"application/json","data":""},"/sw.js":{"type":"application/javascript","data":""},"/_headers":{"type":"application/octet-stream","data":"L3N3LmpzCiAgQ2FjaGUtQ29udHJvbDogbm8tY2FjaGUKL3ByZWNhY2hlLmpzb24KICBDYWNoZS1Db250cm9sOiBuby1jYWNoZQovKgogIFgtQ29udGVudC1UeXBlLU9wdGlvbnM6IG5vc25pZmYKICBSZWZlcnJlci1Qb2xpY3k6IHNhbWUtb3JpZ2luCg=="},"/assets/html2canvas.esm-DXEQVQnt.js":{"type":"application/javascript","data":""},"/assets/index-BeoRn2gJ.js":{"type":"application/javascript","data":""},"/assets/index-D1M4kb4U.css":{"type":"text/css","data":""},"/assets/index-KQmLPhfw.js":{"type":"application/javascript","data":""},"/assets/index.es-B6Tub2-f.js":{"type":"application/javascript","data":""},"/assets/jspdf.es.min-D9a0zaFk.js":{"type":"application/javascript","data":""},"/assets/purify.es-BPuvlvQ_.js":{"type":"application/javascript","data":""},"/fonts/Estedad-OFL.txt":{"type":"text/plain","data":""},"/fonts/Estedad.woff2":{"type":"application/octet-stream","data":""},"/fonts/Vazirmatn-OFL.txt":{"type":"text/plain","data":""},"/fonts/Vazirmatn.woff2":{"type":"application/octet-stream","data":""}};
function serveSite(request){
 if(!['GET','HEAD'].includes(request.method))return new Response(null,{status:405});
 const path=new URL(request.url).pathname;
 const asset=SITE_ASSETS[path]||(path==='/'||!path.split('/').pop().includes('.')?SITE_ASSETS['/index.html']:null);
 if(!asset)return new Response('Not found',{status:404});
 const headers={'Content-Type':asset.type,'Cache-Control':'no-cache','X-Content-Type-Options':'nosniff'};
 return new Response(request.method==='HEAD'?null:Uint8Array.from(atob(asset.data),c=>c.charCodeAt(0)),{headers});
}
